    name: "Math Tutor",
    instructions: "You are a personal math tutor. Write and run code to answer questions.",
    tools: new[] { new CodeInterpreterToolDefinition() }
);

// 2. Create a thread
var thread = await client.Threads.CreateThreadAsync();

// 3. Add a user message to the thread
await client.Messages.CreateMessageAsync(
    thread.Id,
    MessageRole.User,
    "What is the derivative of x^2?"
);

